   427	    loop_res_sync->cur_sb_col[plane][r] = cur;
   428	
   429	    pthread_cond_broadcast(&loop_res_sync->cond_[plane][r]);
   430	    pthread_mutex_unlock(&loop_res_sync->mutex_[plane][r]);
   431	  }
   432	#else
   433	  (void)lr_sync;
   434	  (void)r;
   435	  (void)c;
   436	  (void)sb_cols;
   437	  (void)plane;
   438	#endif  // CONFIG_MULTITHREAD
